<script setup lang="ts">
import {onUnmounted,ref,watch} from 'vue'
import {BrowserQRCodeReader,type IScannerControls} from '@zxing/browser'
import {ElMessage,ElMessageBox} from 'element-plus'
import {previewCode,redeemCode,type CheckinPreview} from '@/api/fulfillment'
import {formatDateTime} from '@/utils/format'
const code=ref(''),preview=ref<CheckinPreview>(),loading=ref(false),busy=ref(false),success=ref(''),camera=ref(false),cameraStarting=ref(false),cameraError=ref(''),video=ref<HTMLVideoElement>(),input=ref<HTMLInputElement>()
let closed=false,epoch=0,cameraEpoch=0,controls:IScannerControls|undefined
watch(code,()=>{epoch++;loading.value=false;preview.value=undefined;success.value=''},{flush:'sync'})
function stop(){cameraEpoch++;controls?.stop();controls=undefined;camera.value=false;cameraStarting.value=false}
async function inspect(){const raw=code.value.trim();if(!/^citygo:checkin:[A-Za-z0-9_-]{43}$/.test(raw)){ElMessage.error('请扫描或填写有效的 CityGo 核销码');return}const run=++epoch;loading.value=true;try{const result=await previewCode(raw);if(run===epoch)preview.value=result}catch{if(run===epoch)preview.value=undefined}finally{if(run===epoch)loading.value=false}}
async function start(){stop();cameraError.value='';cameraStarting.value=true;const run=cameraEpoch;try{const reader=new BrowserQRCodeReader();const c=await reader.decodeFromConstraints({video:{facingMode:{ideal:'environment'}}},video.value!, (result,_error,c)=>{if(result&&run===cameraEpoch){c.stop();stop();code.value=result.getText();void inspect()}});if(run!==cameraEpoch)c.stop();else{controls=c;camera.value=true}}catch{if(run===cameraEpoch)cameraError.value='无法打开摄像头，可改用识别图片或手动填写核销码。'}finally{if(run===cameraEpoch)cameraStarting.value=false}}
async function image(event:Event){const el=event.target as HTMLInputElement,file=el.files?.[0];el.value='';if(!file)return;if(!file.type.startsWith('image/')||file.size>5*1024*1024){ElMessage.error('请选择不超过5MB的二维码图片');return}stop();const url=URL.createObjectURL(file);try{const reader=new BrowserQRCodeReader(),result=await reader.decodeFromImageUrl(url);if(closed)return;code.value=result.getText();await inspect()}catch{ElMessage.error('未识别到二维码，请使用清晰完整的图片')}finally{URL.revokeObjectURL(url)}}
async function redeem(){const selected=preview.value,raw=code.value.trim();if(!selected?.canComplete||busy.value)return;try{await ElMessageBox.confirm('确认核销订单 '+selected.orderNo+'？完成后不释放已履约名额。','确认扫码核销')}catch{return}if(preview.value!==selected||code.value.trim()!==raw)return;busy.value=true;try{await redeemCode(raw);success.value=selected.orderNo;preview.value=undefined;ElMessage.success('核销成功')}catch{}finally{busy.value=false}}
onUnmounted(()=>{closed=true;epoch++;stop()})
</script>
<template><el-card class="desk"><template #header><h2>扫码核销</h2><el-text type="info">先识别并核对预约，再确认核销。仅工作人员可操作。</el-text></template><div class="scan-actions"><el-button :loading="cameraStarting" :disabled="busy" @click="start">打开摄像头</el-button><el-button v-if="camera||cameraStarting" @click="stop">停止扫描</el-button><el-button :disabled="busy" @click="input?.click()">识别二维码图片</el-button><input ref="input" class="file" type="file" accept="image/*" aria-label="二维码图片" @change="image"/></div><video ref="video" v-show="camera||cameraStarting" muted playsinline class="camera"/><el-alert v-if="cameraError" :title="cameraError" type="warning" :closable="false"/><el-form label-position="top"><el-form-item label="核销码"><el-input v-model="code" type="textarea" :rows="2" :maxlength="100" placeholder="也可以粘贴用户出示的核销码" :disabled="busy"/></el-form-item><el-button type="primary" :loading="loading" :disabled="busy||!code.trim()" @click="inspect">校验核销码</el-button></el-form><el-result v-if="success" icon="success" title="核销成功" :sub-title="success"/><section v-if="preview" class="preview"><h3>{{preview.orderNo}}</h3><el-tag>已确认预约 · 版本 {{preview.version}}</el-tag><p v-for="i in preview.detail.items" :key="i.id">{{i.name}} × {{i.quantity}}</p><p v-if="preview.fulfillment.current">当前场次：{{formatDateTime(preview.fulfillment.current.startTime)}} · {{preview.fulfillment.current.address}}</p><p>预约人：{{preview.detail.order.contactName}}</p><el-alert v-if="!preview.canComplete" :title="preview.reason||'当前不满足核销条件'" type="warning" :closable="false"/><el-button type="success" :loading="busy" :disabled="!preview.canComplete" @click="redeem">确认核销</el-button></section></el-card></template>
<style scoped>.desk{max-width:900px}h2{margin:0 0 8px}.scan-actions{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}.scan-actions .el-button{margin:0}.file{display:none}.camera{display:block;width:100%;max-width:500px;border-radius:10px;margin-bottom:20px}.preview{margin-top:24px;padding:20px;border:1px solid var(--el-border-color);border-radius:10px}.preview .el-button{margin-top:16px}.el-form{margin-top:20px}p{line-height:1.6;overflow-wrap:anywhere}</style>
